    // Also update in backend
    fetch(`http://localhost/Tabolator_Casestudy/backend/api/contestants`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ id: id, status: 'Eliminated' })
